import cache from 'src/utils/cache';
import { versionStorageKey } from 'src/utils/appVersionKey';

// Primary: APP_VUE_CURRENT_VERSION from CI/CD (set during deployment)
// Fallback: APP_VERSION from quasar.config.cjs (read from version.txt - available locally)
const APP_VUE_CURRENT_VERSION = process.env.APP_VUE_CURRENT_VERSION?.toString() || process.env.APP_VERSION?.toString() || '0';
// Keep this literal for the same reason as LogoutUtil: this module is imported by
// early auth/settings chunks, so top-level CONSTANTS access can break Vue mount.
const APP_VERSION_KEY = versionStorageKey();

export const AppVersion = {
  setting_name : APP_VERSION_KEY,

  updateVersion () {
    cache.methods.setDataToLocalStorage(this.setting_name, APP_VUE_CURRENT_VERSION);
  }
}
